"""Test the browser-only commitment checker against original CLI-generated bytes."""
from __future__ import annotations

import argparse
import json
import tempfile
import threading
from functools import partial
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from playwright.sync_api import sync_playwright

from model_claim_replay.demo import generate_offline_demo


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--site", type=Path, required=True)
    args = parser.parse_args()
    handler = partial(SimpleHTTPRequestHandler, directory=str(args.site.resolve()))
    server = ThreadingHTTPServer(("127.0.0.1", 0), handler)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    origin = f"http://127.0.0.1:{server.server_port}"
    try:
        with tempfile.TemporaryDirectory() as directory, sync_playwright() as api:
            bundle = Path(directory) / "demo"
            generate_offline_demo(bundle)
            tampered = Path(directory) / "changed.jsonl"
            tampered.write_bytes((bundle / "run/results.jsonl").read_bytes() + b" ")
            wrong_run = Path(directory) / "wrong-run.json"
            data = json.loads((bundle / "run/run.json").read_bytes())
            data["claim_id"] = "different-claim"
            wrong_run.write_text(json.dumps(data), encoding="utf-8")
            browser = api.chromium.launch(headless=True, args=["--no-sandbox"])
            try:
                for width,height in ((1440,900),(390,844)):
                    page = browser.new_page(viewport={"width":width,"height":height})
                    requests = []
                    errors = []
                    page.on("request", lambda request: requests.append(request.url))
                    page.on("pageerror", lambda error: errors.append(str(error)))
                    page.goto(origin + "/check.html", wait_until="load")
                    page.locator("#run-file").set_input_files(bundle / "run/run.json")
                    page.locator("#claim-file").set_input_files(bundle / "claim.json")
                    page.locator("#results-file").set_input_files(bundle / "run/results.jsonl")
                    page.locator("#tasks-file").set_input_files(bundle / "tasks.jsonl")
                    page.locator("#check-submit").click()
                    page.locator('#check-status[data-outcome="match"]').wait_for()
                    assert page.locator('.check-row[data-result="match"]').count() == 4
                    assert "No score or execution verified" in page.locator("#check-status").inner_text()
                    page.locator("#results-file").set_input_files(tampered)
                    assert page.locator(".check-row").count() == 0
                    page.locator("#check-submit").click()
                    page.locator('#check-status[data-outcome="mismatch"]').wait_for()
                    assert page.locator('.check-row[data-result="mismatch"]').count() == 1
                    page.locator("#run-file").set_input_files(wrong_run)
                    page.locator("#check-submit").click()
                    page.locator('#check-status[data-outcome="error"]').wait_for()
                    assert "IDs do not match" in page.locator("#check-status").inner_text()
                    page.get_by_role("button", name="Clear files").click()
                    assert page.locator("#run-file").input_value() == ""
                    assert page.locator(".check-row").count() == 0
                    assert page.locator('#check-status[data-outcome="idle"]').count() == 1
                    assert page.evaluate("document.documentElement.scrollWidth - innerWidth") <= 1
                    assert not errors, errors
                    # After page load the file-check workflow issues no network
                    # request. CSP additionally prohibits all fetch/XHR.
                    assert all(url.startswith(origin + "/") for url in requests), requests
                    allowed = {"/check.html","/style.css","/check.css","/check.js","/favicon.ico"}
                    assert all(url[len(origin):] in allowed for url in requests), requests
                    page.close()
            finally:
                browser.close()
    finally:
        server.shutdown()
        server.server_close()
        thread.join(timeout=5)


if __name__ == "__main__":
    main()
